begin;do $$declare owner_id uuid:=gen_random_uuid();viewer_id uuid:=gen_random_uuid();outsider_id uuid:=gen_random_uuid();hid uuid:=gen_random_uuid();other_hid uuid:=gen_random_uuid();trip uuid;result jsonb;begin insert into fp.households(id,name,owner_user_id)values(hid,'Synthetic Travel Management',owner_id),(other_hid,'Other',outsider_id);insert into fp.members(household_id,user_id,email,display_name,role)values(hid,owner_id,'tm-owner@example.test','Owner','owner'),(hid,viewer_id,'tm-viewer@example.test','Viewer','viewer'),(other_hid,outsider_id,'tm-out@example.test','Outsider','owner');perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'aal','aal2')::text,true);result:=fp.create_travel_trip('Synthetic Wellington','Wellington',current_date,current_date+2);trip:=(result->>'id')::uuid;perform fp.update_travel_trip(trip,'Synthetic Wellington','Wellington',current_date,current_date+2,'NZD',1000,'planned','Synthetic');perform fp.add_trip_traveller(trip,'Synthetic Traveller',viewer_id);perform fp.set_trip_share(trip,viewer_id,'contribute');perform fp.add_travel_cost(trip,null,'transport','paid',250,'NZD',null,null,null,'Synthetic fare');if jsonb_array_length(fp.travel_workspace()->'costs')<>1 then raise exception 'owner cost failed';end if;perform set_config('request.jwt.claims',jsonb_build_object('sub',viewer_id,'aal','aal1')::text,true);if jsonb_array_length(fp.travel_workspace()->'trips')<>1 or jsonb_array_length(fp.travel_workspace()->'costs')<>1 then raise exception 'shared trip unavailable';end if;perform fp.add_travel_cost(trip,null,'food','estimated',100,'NZD',null,null,null,'Synthetic food');perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider_id,'aal','aal2')::text,true);if jsonb_array_length(fp.travel_workspace()->'trips')<>0 then raise exception 'cross household leak';end if;end$$;rollback;
